new:
if (!isDualLabelLayoutPreset() || !shell) {
    canvasEl.style.minHeight = '';
    if (shell) {
        shell.style.width = '';
        shell.style.height = '';
        shell.style.maxWidth = '';
        shell.style.minWidth = '';
        shell.style.minHeight = '';
        shell.style.zoom = '';
    }
    var outerBadgeClear = document.getElementById('barcodeDualOuterSizeBadge');
    if (outerBadgeClear) outerBadgeClear.textContent = '';
    return;
}
var val = barcodeLabelPreset();
if (isDualUnified120x50(val)) {
    layoutDualUnified120x50Preview();
    shell.style.width = '';
    shell.style.height = '';
    shell.style.zoom = '1';
    shell.setAttribute('title', 'Outer preview ' + DUAL_120x50_SCREEN_CM.w + '×' + DUAL_120x50_SCREEN_CM.h + ' cm · print sheet 120×50 mm');
    var outerBadge = document.getElementById('barcodeDualOuterSizeBadge');
    if (!outerBadge) {
        outerBadge = document.createElement('div');
        outerBadge.id = 'barcodeDualOuterSizeBadge';
        outerBadge.className = 'barcode-dual-outer-size-badge';
        shell.parentElement.insertBefore(outerBadge, shell);
    }
    outerBadge.textContent = 'Outer box: ' + DUAL_120x50_SCREEN_CM.w + ' cm × ' + DUAL_120x50_SCREEN_CM.h
        + ' cm · inside: 2× (2 cm × 2.5 cm) · print 120×50 mm';
    var frame = document.getElementById('barcodeDualOuterFrame');
    canvasEl.style.minHeight = Math.max(180, (frame ? frame.offsetHeight : 0) + 56) + 'px';
    if (typeof positionDefaultBarcodesInEachLabel === 'function') {
        positionDefaultBarcodesInEachLabel();
    }
    return;
}
var dims = getDualTagLayoutPx();
